using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>
/// Business layers (Domain, Application) must stay free of technical details.
/// Anything technical goes behind an interface in Application, implemented in Infrastructure.
/// </summary>
public sealed class LayerRulesTests
{
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO",
        "System.Net",
        "System.Data",
        "System.Diagnostics.Process",
        "System.Text.Json",
        "Microsoft.Data",
        "Microsoft.EntityFrameworkCore",
        "Microsoft.Extensions.Http",
    ];

    private static readonly System.Reflection.Assembly Domain = typeof(Money).Assembly;
    private static readonly System.Reflection.Assembly Application = typeof(IPaymentGateway).Assembly;
    private static readonly string InfrastructureName = typeof(HttpPaymentGateway).Assembly.GetName().Name!;

    public static TheoryData<string> Technical => new(TechnicalNamespaces);

    [Theory]
    [MemberData(nameof(Technical))]
    public void Domain_does_not_use_technical_namespaces(string ns) => AssertNoDependency(Domain, ns);

    [Theory]
    [MemberData(nameof(Technical))]
    public void Application_does_not_use_technical_namespaces(string ns) => AssertNoDependency(Application, ns);

    [Fact]
    public void Domain_does_not_depend_on_other_layers()
    {
        AssertNoDependency(Domain, "PaymentAuthorization.Application");
        AssertNoDependency(Domain, InfrastructureName);
    }

    [Fact]
    public void Application_does_not_depend_on_Infrastructure() => AssertNoDependency(Application, InfrastructureName);

    private static void AssertNoDependency(System.Reflection.Assembly assembly, string dependency)
    {
        var result = Types.InAssembly(assembly).ShouldNot().HaveDependencyOn(dependency).GetResult();
        Assert.True(result.IsSuccessful,
            $"{assembly.GetName().Name} must not depend on {dependency}: {string.Join(", ", result.FailingTypeNames ?? [])}");
    }
}
